  handleGoClick = () => {
    this.props.onChange(this.getInputValue())
  }

  render() {
    return (
      <div>
        <p>Type a username or repo full name and hit 'Go':</p>
        <input
          size="45"
          ref={input => (this.input = input)}
          defaultValue={this.props.value}
          onKeyUp={this.handleKeyUp}
